+export function estimateCost(ratePerHour, duration, unit = "hours") {
+  const validUnits = ["hours", "minutes", "seconds", "milliseconds"];
+  
+  if (typeof ratePerHour !== "number" || !Number.isFinite(ratePerHour) || ratePerHour < 0) {
+    throw new TypeError("ratePerHour must be a finite number >= 0");
+  }
+  
+  if (typeof duration !== "number" || !Number.isFinite(duration) || duration < 0) {
+    throw new TypeError("duration must be a finite number >= 0");
+  }
+  
+  if (unit !== "hours" && unit !== "minutes" && unit !== "seconds" && unit !== "milliseconds") {
+    throw new RangeError(`Invalid unit: ${unit}. Must be one of: hours, minutes, seconds, milliseconds`);
+  }
+  
+  let hours;
+  switch (unit) {
+    case "hours":
+      hours = duration;
+      break;
+    case "minutes":
+      hours = duration / 60;
+      break;
+    case "seconds":
+      hours = duration / 3600;
+      break;
+    case "milliseconds":
+      hours = duration / 3600000;
+      break;
+    default:
+      throw new RangeError(`Invalid unit: ${unit}`);
+  }
+  
+  const cost = ratePerHour * hours;
+  
+  // Normalize -0 to 0
+  if (cost === 0) {
+    cost = 0;
+  }
+  
+  return Object.freeze({
+    ratePerHour,
+    duration,
+    unit,
+    hours,
+    cost
+  });
+}

